package main

import (
	"fmt"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

var errType = types.Universe.Lookup("error").Type()

func returnsError(sig *types.Signature) bool {
	r := sig.Results()
	for i := 0; i < r.Len(); i++ {
		if types.Identical(r.At(i).Type(), errType) {
			return true
		}
	}
	return false
}

func main() {
	out := os.Args[1]
	cfg := &packages.Config{Mode: packages.NeedName | packages.NeedTypes}
	pkgs, err := packages.Load(cfg, "std")
	if err != nil {
		panic(err)
	}
	for _, p := range pkgs {
		if strings.Contains(p.PkgPath, "internal") || strings.HasPrefix(p.PkgPath, "vendor/") || p.PkgPath == "unsafe" || p.PkgPath == "syscall/js" || strings.HasPrefix(p.PkgPath, "cmd/") {
			continue
		}
		if p.Types == nil {
			continue
		}
		gen(out, p)
	}
}

type genctx struct {
	imports map[string]string
	n       int
	ok      bool
}

func (g *genctx) qual(p *types.Package) string {
	path := p.Path()
	if strings.Contains(path, "internal") || strings.HasPrefix(path, "vendor/") {
		g.ok = false
	}
	if a, ok := g.imports[path]; ok {
		return a
	}
	a := fmt.Sprintf("i%d", len(g.imports))
	g.imports[path] = a
	return a
}

func (g *genctx) typeStr(t types.Type) string {
	return types.TypeString(t, g.qual)
}

func hasUnexported(t types.Type) bool {
	bad := false
	var visit func(t types.Type, depth int)
	visit = func(t types.Type, depth int) {
		if depth > 5 || bad {
			return
		}
		switch t := t.(type) {
		case *types.Named:
			if !t.Obj().Exported() && t.Obj().Pkg() != nil {
				bad = true
			}
			if t.TypeArgs() != nil {
				bad = true
			}
		case *types.Pointer:
			visit(t.Elem(), depth+1)
		case *types.Slice:
			visit(t.Elem(), depth+1)
		case *types.Array:
			visit(t.Elem(), depth+1)
		case *types.Map:
			visit(t.Key(), depth+1)
			visit(t.Elem(), depth+1)
		case *types.Chan:
			visit(t.Elem(), depth+1)
		case *types.Signature:
			for i := 0; i < t.Params().Len(); i++ {
				visit(t.Params().At(i).Type(), depth+1)
			}
			for i := 0; i < t.Results().Len(); i++ {
				visit(t.Results().At(i).Type(), depth+1)
			}
		case *types.Struct:
			bad = true
		case *types.Interface:
			if t.NumMethods() > 0 || t.NumEmbeddeds() > 0 {
				bad = true
			}
		case *types.TypeParam:
			bad = true
		case *types.Alias:
			visit(types.Unalias(t), depth)
		}
	}
	visit(t, 0)
	return bad
}

func (g *genctx) args(sig *types.Signature) (string, bool) {
	var parts []string
	n := sig.Params().Len()
	if sig.Variadic() {
		n--
	}
	for i := 0; i < n; i++ {
		t := sig.Params().At(i).Type()
		if hasUnexported(t) {
			return "", false
		}
		parts = append(parts, "*new("+g.typeStr(t)+")")
	}
	return strings.Join(parts, ", "), true
}

func gen(out string, p *packages.Package) {
	g := &genctx{imports: map[string]string{}}
	g.imports[p.PkgPath] = "P"
	var lines []string
	scope := p.Types.Scope()
	names := scope.Names()
	sort.Strings(names)
	for _, name := range names {
		obj := scope.Lookup(name)
		if !obj.Exported() {
			continue
		}
		switch o := obj.(type) {
		case *types.Func:
			sig := o.Type().(*types.Signature)
			if sig.TypeParams() != nil || !returnsError(sig) {
				continue
			}
			g.ok = true
			a, ok := g.args(sig)
			if !ok || !g.ok {
				continue
			}
			lines = append(lines, fmt.Sprintf("\tP.%s(%s)", name, a))
		case *types.TypeName:
			if o.IsAlias() {
				continue
			}
			named, ok := o.Type().(*types.Named)
			if !ok || named.TypeParams() != nil {
				continue
			}
			// method set of *T and T, including promoted methods
			var mset *types.MethodSet
			isIface := types.IsInterface(named)
			if isIface {
				mset = types.NewMethodSet(named)
			} else {
				mset = types.NewMethodSet(types.NewPointer(named))
			}
			for i := 0; i < mset.Len(); i++ {
				sel := mset.At(i)
				m := sel.Obj().(*types.Func)
				if !m.Exported() {
					continue
				}
				sig := m.Type().(*types.Signature)
				if !returnsError(sig) {
					continue
				}
				g.ok = true
				a, ok := g.args(sig)
				if !ok || !g.ok {
					continue
				}
				recv := ""
				if isIface {
					recv = fmt.Sprintf("(*new(P.%s))", name)
				} else {
					recv = fmt.Sprintf("(new(P.%s))", name)
				}
				lines = append(lines, fmt.Sprintf("\t%s.%s(%s)", recv, m.Name(), a))
			}
		}
	}
	if len(lines) == 0 {
		return
	}
	dir := filepath.Join(out, strings.ReplaceAll(p.PkgPath, "/", "_"))
	os.MkdirAll(dir, 0755)
	var sb strings.Builder
	sb.WriteString("package x\n\nimport (\n")
	paths := make([]string, 0, len(g.imports))
	for path := range g.imports {
		paths = append(paths, path)
	}
	sort.Strings(paths)
	for _, path := range paths {
		fmt.Fprintf(&sb, "\t%s %q\n", g.imports[path], path)
	}
	sb.WriteString(")\n\nfunc F() {\n")
	for _, l := range lines {
		sb.WriteString(l + "\n")
	}
	sb.WriteString("}\n")
	os.WriteFile(filepath.Join(dir, "x.go"), []byte(sb.String()), 0644)
}
