// Command errcheck reports call sites whose error results are silently
// discarded.
package main

import (
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"errcheck-clone/internal/lint"
)

const (
	statusClean   = 0
	statusIssues  = 1
	statusFailure = 2
)

func main() {
	os.Exit(run(os.Args, os.Stdout, os.Stderr))
}

// tagFlag accumulates build tags given as comma and/or space separated lists.
type tagFlag []string

func (t *tagFlag) String() string {
	if t == nil {
		return ""
	}
	return strings.Join(*t, ",")
}

func (t *tagFlag) Set(value string) error {
	parts := strings.FieldsFunc(value, func(r rune) bool {
		return r == ',' || r == ' '
	})
	*t = append(*t, parts...)
	return nil
}

// regexpFlag holds the deprecated pkg:regex ignore pairs.
type regexpFlag map[string]*regexp.Regexp

func (r regexpFlag) String() string {
	if len(r) == 0 {
		return ""
	}
	var parts []string
	for pkg, re := range r {
		parts = append(parts, pkg+":"+re.String())
	}
	return strings.Join(parts, ",")
}

func (r regexpFlag) Set(value string) error {
	if value == "" {
		return nil
	}
	for _, item := range strings.Split(value, ",") {
		pkg, expr := "", item
		if i := strings.Index(item, ":"); i >= 0 {
			pkg, expr = item[:i], item[i+1:]
		}
		re, err := regexp.Compile(expr)
		if err != nil {
			return err
		}
		r[pkg] = re
	}
	return nil
}

func run(args []string, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet(args[0], flag.ContinueOnError)
	fs.SetOutput(stderr)

	var (
		tags      tagFlag
		ignore    = regexpFlag{}
		opts      lint.Options
		abspath   bool
		exclFile  string
		exclOnly  bool
		ignorePkg string
		modFlag   string
	)

	fs.BoolVar(&opts.Blank, "blank", false, "if true, check for errors assigned to blank identifier")
	fs.BoolVar(&opts.Asserts, "asserts", false, "if true, check for ignored type assertion results")
	fs.BoolVar(&opts.SkipTests, "ignoretests", false, "if true, checking of _test.go files is disabled")
	fs.BoolVar(&opts.SkipGenerated, "ignoregenerated", false, "if true, checking of files with generated code is disabled")
	fs.BoolVar(&opts.Verbose, "verbose", false, "produce more verbose logging")
	fs.BoolVar(&abspath, "abspath", false, "print absolute paths to files")
	fs.Var(&tags, "tags", "comma or space-separated list of build tags to include")
	fs.StringVar(&ignorePkg, "ignorepkg", "", "comma-separated list of package paths to ignore")
	fs.Var(ignore, "ignore", "[deprecated] comma-separated list of pairs of the form pkg:regex\n"+
		"            the regex is used to ignore names within pkg.")
