	IgnoreRegexps  map[string]*regexp.Regexp
	IgnorePackages map[string]bool

	BuildFlags []string
	Log        io.Writer
}

// Issue describes one unchecked error.
type Issue struct {
	Pos  token.Position
	Text string // trimmed source line
	Func string // qualified callee name, if known
}

const loadMode = packages.NeedName |
	packages.NeedFiles |
	packages.NeedImports |
	packages.NeedTypes |
	packages.NeedTypesSizes |
	packages.NeedSyntax |
	packages.NeedTypesInfo |
	packages.NeedModule

func load(opts *Options, patterns []string) ([]*packages.Package, error) {
	cfg := &packages.Config{
		Mode:       loadMode,
		Tests:      !opts.SkipTests,
		BuildFlags: opts.BuildFlags,
	}
	pkgs, err := packages.Load(cfg, patterns...)
	if err != nil {
		return nil, err
	}
	for _, p := range pkgs {
		if len(p.Errors) > 0 {
			return nil, fmt.Errorf("errors while loading package %s: %v", p.ID, p.Errors)
		}
	}
	return pkgs, nil
}

// Run loads the packages matching patterns and returns the sorted,
// de-duplicated list of unchecked errors found in them.
func Run(opts *Options, patterns []string) ([]Issue, error) {
	pkgs, err := load(opts, patterns)
	if err != nil {
		return nil, err
	}

	src := newSourceCache()
	var (
		mu  sync.Mutex
		all []Issue
		wg  sync.WaitGroup
	)
	for _, p := range pkgs {
		wg.Add(1)
		go func(p *packages.Package) {
			defer wg.Done()
			found := checkPackage(opts, p, src)
			mu.Lock()
			all = append(all, found...)
			mu.Unlock()
		}(p)
	}
	wg.Wait()

	return uniqueSorted(all), nil
}

func checkPackage(opts *Options, p *packages.Package, src *sourceCache) []Issue {
	if opts.Verbose && opts.Log != nil {
		fmt.Fprintf(opts.Log, "checking %s\n", p.PkgPath)
	}
	w := &walker{
		opts: opts,
		info: p.TypesInfo,
		fset: p.Fset,
		src:  src,
	}
	for _, f := range p.Syntax {
		if opts.SkipGenerated && isGenerated(f) {
			continue
		}
		w.walkFile(f)
	}
	return w.issues
}

func lessIssue(a, b Issue) bool {
	if a.Pos.Filename != b.Pos.Filename {
		return a.Pos.Filename < b.Pos.Filename
	}
	if a.Pos.Line != b.Pos.Line {
		return a.Pos.Line < b.Pos.Line
	}
	if a.Pos.Column != b.Pos.Column {
		return a.Pos.Column < b.Pos.Column
	}
	return a.Text < b.Text
}

func uniqueSorted(list []Issue) []Issue {
	sort.SliceStable(list, func(i, j int) bool { return lessIssue(list[i], list[j]) })
	out := list[:0]
	for i, is := range list {
