package lint

import (
	"go/ast"
	"go/token"
	"go/types"
	"regexp"
	"strings"
)

var generatedMarker = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)

// isGenerated reports whether any comment of the file carries the
// standard "Code generated ... DO NOT EDIT." marker.
func isGenerated(f *ast.File) bool {
	for _, group := range f.Comments {
		for _, c := range group.List {
			if generatedMarker.MatchString(c.Text) {
				return true
			}
		}
	}
	return false
}

var errorIface = types.Universe.Lookup("error").Type().Underlying().(*types.Interface)

type walker struct {
	opts   *Options
	info   *types.Info
	fset   *token.FileSet
	src    *sourceCache
	issues []Issue
}

func (w *walker) walkFile(f *ast.File) {
	ast.Walk(w, f)
}

func (w *walker) Visit(node ast.Node) ast.Visitor {
	switch n := node.(type) {
	case *ast.ExprStmt:
		if call, ok := n.X.(*ast.CallExpr); ok {
			w.checkDiscarded(call)
		}
	case *ast.GoStmt:
		w.checkDiscarded(n.Call)
	case *ast.DeferStmt:
		w.checkDiscarded(n.Call)
	case *ast.AssignStmt:
		if !w.assignment(n.Lhs, n.Rhs) {
			return nil
		}
	case *ast.GenDecl:
		for _, spec := range n.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok || len(vs.Values) == 0 {
				continue
			}
			lhs := make([]ast.Expr, len(vs.Names))
			for i, id := range vs.Names {
				lhs[i] = id
			}
			if !w.assignment(lhs, vs.Values) {
				return nil
			}
		}
	case *ast.TypeAssertExpr:
		if w.opts.Asserts && n.Type != nil {
			w.report(n.Pos(), nil)
